import React from 'react';

const Footer = () => {
  return (
    <footer className="w-full py-6 bg-black border-t border-raw-bone/5">
      <div className="flex flex-col items-center justify-center space-y-2">
        <p className="text-[8px] text-raw-bone/20 uppercase tracking-[0.4em] font-inter">
          RAW. SESSION v1.0.4 — International Build
        </p>
        <div className="flex space-x-4 opacity-30">
          <div className="h-[1px] w-8 bg-raw-bone"></div>
          <div className="h-[1px] w-8 bg-raw-cyan"></div>
          <div className="h-[1px] w-8 bg-raw-red"></div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
